    var out: std.ArrayListUnmanaged(u8) = .empty;
    const al = cx_gpa;
    var i: usize = 0;
    while (i < s.len) {
        const b0: i64 = s[i];
        var code: i64 = b0;
        if (b0 & 128 == 0) {
            i += 1;
        } else if (b0 & 224 == 192) {
            code = 128 + ((b0 & 31) << 6) + (s[i + 1] & 63);
            i += 2;
        } else if (b0 & 240 == 224) {
            code = 2176 + ((b0 & 15) << 12) + (@as(i64, s[i + 1] & 63) << 6) + (s[i + 2] & 63);
            i += 3;
        } else {
            code = 67712 + ((b0 & 7) << 18) + (@as(i64, s[i + 1] & 63) << 12) + (@as(i64, s[i + 2] & 63) << 6) + (s[i + 3] & 63);
            i += 4;
        }
        const cp: u32 = @intCast(cx_cce_to_cp(code));
        if (cp < 128) {
            out.append(al, @intCast(cp)) catch @panic("oom");
        } else if (cp < 2048) {
            out.append(al, @intCast(192 + (cp >> 6))) catch @panic("oom");
            out.append(al, @intCast(128 + (cp & 63))) catch @panic("oom");
        } else if (cp < 65536) {
            out.append(al, @intCast(224 + (cp >> 12))) catch @panic("oom");
            out.append(al, @intCast(128 + ((cp >> 6) & 63))) catch @panic("oom");
            out.append(al, @intCast(128 + (cp & 63))) catch @panic("oom");
        } else {
            out.append(al, @intCast(240 + (cp >> 18))) catch @panic("oom");
            out.append(al, @intCast(128 + ((cp >> 12) & 63))) catch @panic("oom");
            out.append(al, @intCast(128 + ((cp >> 6) & 63))) catch @panic("oom");
            out.append(al, @intCast(128 + (cp & 63))) catch @panic("oom");
        }
    }
    return out.items;
}
// One allocation, not two: the digits land in a stack scratch first
// (i64 needs at most 20 bytes), then the CCE translation is the only
// heap object. The double allocation left the ASCII copy stranded on
// the frontier where it blocked in-place extension of whatever grew
// next.
fn cx_show_int(n: i64) []const u8 {
    var cx_tmp: [24]u8 = undefined;
    const ascii = std.fmt.bufPrint(&cx_tmp, "{d}", .{n}) catch unreachable;
    const buf = cx_raw(u8, ascii.len);
    for (ascii, 0..) |cx_ch, cx_i| {
        buf[cx_i] = if (cx_ch == '-') 73 else 3 + (cx_ch - '0');
    }
    return buf;
}
fn cx_print_line(s: []const u8) void {
    if (cx_host_print) |p| p(cx_cce_to_utf8(s));
}
/// Library mode: a host's own print for the chapter's Console lines; null,
/// stderr as a program's.
pub var cx_host_print: ?*const fn ([]const u8) void = null;
fn cx_print(s: []const u8) void {
    if (cx_host_print) |p| p(cx_cce_to_utf8(s));
}


// ========================================================================
// THE LIBRARY'S SHARED FACE (cobble-webbox, src/library.zig.in, appended by
// tools/regen.shale to every library, before the application's own): what
// library mode will emit for any chapter a host calls instead of runs. In
// this file, so it reaches the chapter's own definitions, which the
// emitter leaves private.
// ========================================================================

/// ASCII as the chapter's text holds it (CCE): each byte the code whose
/// code point it is, by the runtime's own table; a byte that is no ASCII,
/// or ASCII the table does not hold, is refused.
fn asciiToCce(s: []const u8) error{NotAscii}![]const u8 {
    const out = cx_raw(u8, s.len);
    for (s, 0..) |c, i| out[i] = ascii_to_cce[c] orelse return error.NotAscii;
    return out;
}

const ascii_to_cce: [256]?u8 = blk: {
    var t: [256]?u8 = @splat(null);
    for (cce_table, 0..) |cp, code| {
        if (cp < 128 and t[cp] == null) t[cp] = @intCast(code);
    }
    break :blk t;
};
// ========================================================================
// A UOAIX PROOF'S FACE (cobble-webbox, src/uo_api.zig.in, appended
// by tools/regen.shale after src/library.zig.in).
// ========================================================================

/// What a host calls: one of apps/uoaix/proofs/, the proof a program runs
/// as its `opening`, its Console lines to the host's sink.
pub const api = struct {
    /// Bytes of the Codex heap in use since its base.
    pub fn heapUsed() i64 {
        return cx_hp - cx_heap_floor;
    }
    const cx_heap_floor: i64 = 6291456;

    /// Everything given back: nothing from before may be used after it.
    pub fn heapReset() void {
        cx_hp = cx_heap_floor;
    }

    /// The Codex heap's region, given by the host before the first
    /// allocation and kept for the process: zeroed, as bare metal's boot
    /// zero-fills its heap. Giving the same region again changes nothing.
    pub fn heapGive(region: []align(4096) u8) void {
        if (cx_heap_mem.len != 0) {
            if (cx_heap_mem.ptr == region.ptr and cx_heap_mem.len == region.len) return;
            @panic("uo: the heap already has its region");
        }
        cx_heap_mem = region;
        cx_heap_reserve = region.len;
    }

    /// The proof, once, from a fresh heap: each line it prints, UTF-8, to
    /// `sink`, valid only during that call.
    pub fn runProof(sink: *const fn ([]const u8) void) void {
        cx_hp = cx_heap_floor;
        cx_host_print = sink;
        defer cx_host_print = null;
        opening();
    }
};
